warehouse_a = {'apple': 10, 'banana': 5}
warehouse_b = {'banana': 3, 'cherry': 8}
total_stock = dict(warehouse_a)
for name, count in warehouse_b.items():
    total_stock[name] = total_stock.get(name, 0) + count
common = sorted(set(warehouse_a) & set(warehouse_b))
print(total_stock)
print(common)
